import React from 'react';
import './TentsPage.css';

const TentsPage = () => {
  const categories = [
    { name: "MS TENTS", id: 1 },
    { name: "ALUMINIUM TENTS", id: 2 },
    { name: "PVC TENTS", id: 3 },
    { name: "CUSTOM DESIGNS", id: 4 }
  ];

  return (
    <div className="tents-page">
      <div className="quadrants-grid">
        {categories.map((category) => (
          <div key={category.id} className="quadrant">
            <button className="category-pill">
              {category.name}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TentsPage;
